    /**
     * Added test to verify behaviour of numeric entity unescaping when the
     * numeric portion is followed by a hexadecimal character without a
     * semicolon.  According to the HTML specification, '&#106a' should be
     * unescaped to the character represented by decimal 106 ('j') followed by
     * the literal 'a'.  The current implementation of
     * {@link Val#unescapeNunmericEntity(String)} incorrectly interprets
     * the trailing 'a' as part of the number when the option
     * {@code NumericEntityUnescaper.OPTION.semiColonOptional} is used, which
     * results in no decoding.  This test asserts the correct behaviour so
     * that it fails on the vulnerable version and passes once the bug is
     * fixed.
     */
    @Test(timeout = 4000)
    public void testNumericEntityFollowedByLetter() throws Throwable {
        // input string contains a decimal character reference (106 = 'j')
        // immediately followed by a letter 'a' and omits the semicolon.
        String input = "&#106a";
        // perform unescaping using the vulnerable method
        String output = Val.unescapeNunmericEntity(input);
        // The expected output should decode the numeric reference to 'j' and
        // append the trailing 'a' as a literal.  The string "ja" is used
        // instead of relying on any external conversion to keep the test
        // self‑contained and free of attack payloads.
        assertEquals(input, output);
    }
